#define main legacy_main
#include "segment-reduce-cuda/main.cu"
#undef main
#include <vector>
#include <cmath>
int main(){int n=16384,repeat=10;std::vector<int>input(n),key(n),values;for(int i=0;i<n;i++)input[i]=i%17-8;int *dx,*dk;cudaMalloc(&dx,n*4);cudaMalloc(&dk,n*4);cudaMemcpy(dx,input.data(),n*4,cudaMemcpyHostToDevice);for(int trial=1;trial<=5;trial++){values.clear();double total=0.;bool correct=true;for(int s=16;s<=16384;s*=2){int groups=n/s;for(int i=0;i<n;i++)key[i]=i/s;cudaMemcpy(dk,key.data(),n*4,cudaMemcpyHostToDevice);int *dy,*dyk;cudaMalloc(&dy,groups*4);cudaMalloc(&dyk,groups*4);auto warm=thrust::reduce_by_key(thrust::device,dk,dk+n,dx,dyk,dy);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;correct &=warm.first-dyk==groups;cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)thrust::reduce_by_key(thrust::device,dk,dk+n,dx,dyk,dy);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<int>out(groups),outkey(groups);cudaMemcpy(out.data(),dy,groups*4,cudaMemcpyDeviceToHost);cudaMemcpy(outkey.data(),dyk,groups*4,cudaMemcpyDeviceToHost);for(int g=0;g<groups;g++){int want=0;for(int i=g*s;i<(g+1)*s;i++)want+=input[i];correct &=out[g]==want&&outkey[g]==g;}values.insert(values.end(),outkey.begin(),outkey.end());values.insert(values.end(),out.begin(),out.end());cudaFree(dy);cudaFree(dyk);}char file[32];snprintf(file,sizeof(file),"trial_%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(values.data(),4,values.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.14g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"timing_region\":\"sum_eleven_segment_size_operation_means\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,correct?"true":"false",values.size(),correct?0:1,repeat,file,values.size());if(!correct)return 1;}cudaFree(dx);cudaFree(dk);}
